import numpy as np
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
G={k:F[k].astype(np.float64) for k in F.files if k!='y'}
S={k:(v-v.mean(0))/(v.std(0)+1e-9) for k,v in G.items()}
def cv_dual(keys,lams,w=None):
    w=w or [1.0]*len(keys)
    X=np.concatenate([wi*S[k] for k,wi in zip(keys,w)],1)
    K=X@X.T
    res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f; Y=np.eye(8)[y[tr]]-1/8; ym=Y.mean(0)
            Ktr=K[np.ix_(tr,tr)]; n=tr.sum(); H=np.eye(n)-1/n
            Kc=H@Ktr@H; Kte=(K[np.ix_(te,tr)]-Ktr.mean(0))@H - 0  # approx centering
            Kte=K[np.ix_(te,tr)]-K[np.ix_(te,tr)].mean(1,keepdims=True)-Ktr.mean(0)[None]+Ktr.mean()
            for l in lams:
                a=np.linalg.solve(Kc+l*np.eye(n),Y-ym); res[l]+=((Kte@a+ym).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
print('C9M9', cv_dual(['C9','M9'],[300,1000]))
print('+M0', cv_dual(['C9','M9','M0'],[300,1000]))
for extra in [['M0','M3'],['M0','M5'],['M0','M7'],['M0','M2','M5'],['M0','M1'],['M0','M3','M6']]:
    print('+',extra, cv_dual(['C9','M9']+extra,[300,1000,2000]))
print('+M0 w.7', cv_dual(['C9','M9','M0'],[300,1000],[1,1,0.7]))
print('+M0 w1.4', cv_dual(['C9','M9','M0'],[300,1000],[1,1,1.4]))
